svg.script:
(function(){
 const NS="http://www.w3.org/2000/svg";
 function fmt(d){return new Intl.DateTimeFormat("en-US",{hour:"numeric",minute:"2-digit",hour12:true,timeZone:"America/Denver"}).format(d);}
 function clock(){const n=new Date(),c=document.getElementById("statusClock");if(c)c.textContent=fmt(n);
  const h=[...document.querySelectorAll("text")].find(t=>/^Today /.test(t.textContent));if(h)h.textContent="Today "+fmt(n);
  let b=new Date(n);b.setSeconds(0,0);b.setMinutes(b.getMinutes()-6);for(let i=1;i<=8;i++){let e=document.getElementById("msgTime"+i);if(e)e.textContent=fmt(new Date(b.getTime()+(i-1)*60000));}}
 function convertShape(g){let sh=g.querySelector("path.incoming,path.outgoing");if(!sh)return null;
  if(sh.tagName.toLowerCase()==="path"){let b=sh.getBBox(),r=document.createElementNS(NS,"rect");r.setAttribute("class",sh.getAttribute("class"));r.setAttribute("x",b.x);r.setAttribute("y",b.y);r.setAttribute("width",b.width);r.setAttribute("height",b.height);r.setAttribute("rx","28");r.setAttribute("fill",getComputedStyle(sh).fill);sh.parentNode.insertBefore(r,sh);sh.remove();sh=r;}return sh;}
 function layoutOne(g){let r=convertShape(g);if(!r)return;let texts=[...g.querySelectorAll("text.msg")];if(!texts.length)return;
  let x=+r.getAttribute("x"),y=+r.getAttribute("y"),w=+r.getAttribute("width"),h=+r.getAttribute("height");
  let outgoing=r.getAttribute("class").includes("outgoing"),pad=30,available=w-pad*2,lineHeight=46;
  let top=Infinity,bottom=-Infinity,maxLineWidth=0;
  texts.forEach(el=>{let raw=el.getAttribute("data-raw");if(raw==null){raw=el.textContent.replace(/\s+/g," ").trim();el.setAttribute("data-raw",raw);}
   el.setAttribute("contenteditable","true");el.style.cursor="text";
   let probe=document.createElementNS(NS,"text");probe.setAttribute("class",el.getAttribute("class"));probe.setAttribute("visibility","hidden");g.appendChild(probe);
   let lines=[],line="";raw.split(/\s+/).forEach(word=>{let test=line?line+" "+word:word;probe.textContent=test;
    if(line&&probe.getComputedTextLength()>available){lines.push(line);line=word;}else line=test;});if(line)lines.push(line);
   probe.remove();let ex=+el.getAttribute("x"),ey=+el.getAttribute("y");while(el.firstChild)el.removeChild(el.firstChild);
   lines.forEach((txt,i)=>{let sp=document.createElementNS(NS,"tspan");sp.setAttribute("x",ex);sp.setAttribute("dy",i?lineHeight:0);sp.textContent=txt;el.appendChild(sp);});
   top=Math.min(top,ey);bottom=Math.max(bottom,ey+(lines.length-1)*lineHeight);lines.forEach(t=>maxLineWidth=Math.max(maxLineWidth,measure(t,el.getAttribute("class"))));
  });
  function measure(t,cl){let z=document.createElementNS(NS,"text");z.setAttribute("class",cl);z.setAttribute("visibility","hidden");z.textContent=t;g.appendChild(z);let a=z.getComputedTextLength();z.remove();return a;}
  let newH=Math.max(h,bottom-y+lineHeight+24),newW=Math.max(w,maxLineWidth+pad*2);
  r.setAttribute("height",newH);r.setAttribute("width",newW);
  // Preserve left alignment for incoming, right edge alignment for outgoing bubbles.
  if(outgoing)r.setAttribute("x",x+w-newW);
 }
 function layout(){document.querySelectorAll("g.bubble").forEach(layoutOne);}
 function addChecks(){document.querySelectorAll("path.tick").forEach(old=>{let parent=old.parentNode;old.remove();
  let x=974,y=1240;let c=document.createElementNS(NS,"text");c.setAttribute("class","blueChecks");c.setAttribute("fill","#087cff");c.setAttribute("font-size","24");c.setAttribute("font-weight","700");c.setAttribute("text-anchor","end");c.setAttribute("x",1000);c.setAttribute("y",y);c.textContent="✓✓";parent.appendChild(c);});}
 function init(){clock();setInterval(clock,1000);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(layout);else setTimeout(layout,300);
  document.addEventListener("input",e=>{let t=e.target.closest&&e.target.closest("text.msg");if(t){t.setAttribute("data-raw",t.textContent.replace(/\s+/g," ").trim());layout();}});
 }
 if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init();
})();
